#!/usr/bin/env python3
"""Regenerates lib/codegen/bench_schema.dart + bench_refs.dart (N flat fields),
then run `dart run build_runner build` to refresh bench_schema.kfg.dart."""
import sys
N = int(sys.argv[1]) if len(sys.argv) > 1 else 100
fields = "\n".join(f"      \'field{i}\': ks.string().min(3)," for i in range(N))
open("lib/codegen/bench_schema.dart", "w").write(
    "// GENERATED BY tool/gen_bench_schema.py\n\n"
    "@keyedSchema\nlibrary;\n\n"
    "import \'package:keyed_form_schema/keyed_form_schema.dart\';\n\n"
    "part \'bench_schema.kfg.dart\';\n\n"
    "final benchSchema = ks.object(className: \'Bench100\', {\n"
    + fields + "\n});\n")
refs = ",\n".join(f"  Bench100Fields.field{i}" for i in range(N))
open("lib/codegen/bench_refs.dart", "w").write(
    "// GENERATED BY tool/gen_bench_schema.py\n\n"
    "import \'package:keyed_form/keyed_form.dart\';\n\n"
    "import \'bench_schema.dart\';\n\n"
    "final List<FieldRef<Bench100Schema, String>> bench100Refs = [\n"
    + refs + ",\n];\n\n"
    "Bench100Schema benchSeed() => Bench100Schema.create("
    + ", ".join(f"field{i}: \'val\'" for i in range(N)) + ");\n")
